mapper.select:
select
pro.P_Id as pId, con.Con_Name as conName, con.Con_Id as conId, con.Con_Party_B_Id as conPartyBId, c2.C_Name_History as conPartyBNameHistory, c3.C_Name_History as wiUnitNameHistory, c2.C_Name as conPartyBName, c3.C_Name as wiUnitName, c2.C_Abbreviation as conPartyBAbbName, c3.C_Abbreviation as wiUnitAbbName, mn.Wi_State as wiState, mn.Wi_Create_Uid as wiCreateUid, mn.Wi_Create_Uname as wiCreateUname, mn.Wi_Create_Time as wiCreateTime, mwd.* from Me_Witness_Dtl mwd left join Me_Witness_Inspection mn on mn.Wi_Id=mwd.Wi_Id left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_Company c2 on con.Con_Party_B_Id=c2.C_Id left join SYS_Company c3 on mn.Wi_Unit_Id=c3.C_Id ${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.Wi_Unit_Id=#{params.wiUnitId}
and mn.P_Id=#{params.pId}
and mn.Con_Id=#{params.conId}
and mwd.Wi_Id = #{params.wiId}
and mwd.Wd_Result = #{params.wdResult}
and mn.Wi_State = #{params.wiState}
and INSTR(mwd.Wd_Name,#{params.wdName})
and INSTR(mwd.Wd_Code,#{params.wdCode})
and mwd.Wi_Id in (select Wi_Id from Me_Inspection_Report where Ir_State!=3)
and mwd.Wi_Id not in (select Wi_Id from Me_Inspection_Report where Wi_Id is not null and Ir_State!=3)
order by mwd.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mwd.Wd_Create_Time DESC

select
con.Con_Name as conName, con.Con_Id as conId, con.Con_Party_B_Id as conPartyBId, con2.Con_Name as eaPurchaseContractName, mtl.Met_Name as metName, c2.C_Name_History as conPartyBNameHistory, c3.C_Name_History as wiUnitNameHistory, c2.C_Name as conPartyBName, c3.C_Name as wiUnitName, c2.C_Abbreviation as conPartyBAbbName, c3.C_Abbreviation as wiUnitAbbName, mea.Ea_Code as eaCode, mea.Ea_Date as eaDate, mea.P_Id as pId, ead.Ead_Standard_Type as eadStandardType, ead.Ead_Count as eadCount, ead.Ead_Brand_Name as eadBrandName, ead.Ead_Supplier_Name as eadSupplierName, ead.Ead_Batch_Number as eadBatchNumber, ead.Ead_Supply_Order_No as eadSupplyOrderNo, mn.Wi_State as wiState, mn.Wi_Create_Uid as wiCreateUid, mn.Wi_Create_Uname as wiCreateUname, mn.Wi_Create_Time as wiCreateTime, mwd.* from Me_Witness_Dtl mwd left join Me_Enter_Apply_Dtl ead on ead.Ead_Id=mwd.Ead_Id left join Me_Enter_Apply mea on mea.Ea_Id=ead.Ea_Id left join Con_Contract con on con.Con_Id=mea.Con_Id left join Con_Contract con2 on con2.Con_Id=mea.Ea_Purchase_Contract left join Pre_Project pro on pro.P_Id=mea.P_Id
left join Me_Type_Library mtl on mtl.Met_Id=ead.Met_Id left join SYS_Company c2 on con.Con_Party_B_Id=c2.C_Id left join Me_Witness_Inspection mn on mn.Wi_Id=mwd.Wi_Id left join SYS_Company c3 on mn.Wi_Unit_Id=c3.C_Id ${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.Wi_Unit_Id=#{params.wiUnitId}
and mea.P_Id=#{params.pId}
and mea.Con_Id=#{params.conId}
and mwd.Wi_Id = #{params.wiId}
and mwd.Wd_Result = #{params.wdResult}
and mtl.Met_Name like concat('%',#{params.metName},'%')
and mea.Ea_Code like concat('%',#{params.eaCode},'%')
and INSTR(mwd.Wd_Code,#{params.wdCode})
and INSTR(mwd.Wd_Name,#{params.wdName})
and mn.Wi_State = #{params.wiState}
and mwd.Wi_Id in (select Wi_Id from Me_Inspection_Report where Ir_State!=3)
and mwd.Wi_Id not in (select Wi_Id from Me_Inspection_Report where Wi_Id is not null and Ir_State!=3)
order by mwd.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mwd.Wd_Create_Time DESC
